#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's quoting undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"; fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line). Idempotent. Creates ENV_FILE at mode 0600; writes through a symlink
# and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Ticket 02 setup for coi-poc. Run from the coi-poc folder: bash scripts/wizard.sh
# Values go to .env (gitignored). The Gemini key goes into Script Properties in
# the browser and never passes through this script. Keep the Workspace domain
# out of every tracked file: web app URLs that hold it stay in .env.

TOTAL_STAGES=11

if [[ ! -t 0 ]]; then
  printf 'This wizard needs your keyboard. Open Git Bash, cd to coi-poc, then run: bash scripts/wizard.sh\n' >&2
  exit 1
fi

banner "COI proof of concept: Apps Script setup"

stage "Tools"
say "This wizard needs Node 24 or later and clasp (the Apps Script command line)."
node --version || { warn "Node is missing. Install Node 24, then run the wizard again."; exit 1; }
if ! command -v clasp >/dev/null 2>&1; then
  if confirm "clasp is missing. Install it now with: npm install -g @google/clasp"; then
    npm install -g @google/clasp
  else
    warn "Install clasp, then run the wizard again."; exit 1
  fi
fi
clasp --version
pause

stage "Turn on the Apps Script API"
say "clasp can create and push projects only when the Apps Script API is on for your account."
open_url "https://script.google.com/home/usersettings"
step "Sign in with your Workspace account (not a work or client account)."
step "Set 'Google Apps Script API' to On."
pause "Press Enter when the setting shows On."

stage "Sign in to clasp"
say "A browser window opens. Pick the same Workspace account and allow access."
note "clasp stores its token in your home folder (~/.clasprc.json), outside the repo."
if confirm "Sign in now?"; then clasp login; else note "Skipped. clasp uses the sign-in it already has."; fi
pause

stage "Workspace edition"
say "Apps Script quotas depend on the edition (see docs/research/apps-script-quotas.md)."
open_url "https://admin.google.com/ac/billing/subscriptions"
step "Find the Google Workspace subscription on the Subscriptions page."
step "Copy the edition name, for example 'Business Starter'."
ask WORKSPACE_EDITION "Workspace edition:"
write_env WORKSPACE_EDITION "$WORKSPACE_EDITION"

stage "Create the script project and push the code"
if [[ -f .clasp.json ]]; then
  note ".clasp.json exists, so the script project exists. No new project is made."
else
  say "clasp makes a standalone script project and writes .clasp.json (gitignored)."
  say "clasp also writes its own appsscript.json. The wizard keeps a copy of the repo's file and puts it back."
  if confirm "Create the script project 'COI Compliance (Sample data)'?"; then
    cp appsscript.json appsscript.json.keep
    clasp create --type standalone --title "COI Compliance (Sample data)"
    mv -f appsscript.json.keep appsscript.json
  else
    warn "No project, no push. Run the wizard again when you are ready."; exit 1
  fi
fi
SCRIPT_ID=$(node -e "console.log(require('./.clasp.json').scriptId)")
write_env SCRIPT_ID "$SCRIPT_ID"
say "Pushing src/ and appsscript.json. .claspignore keeps tests and docs out."
clasp push --force
pause

stage "Gemini API key (Script Properties)"
say "Ticket 02 uses a canned reading, so the key is not needed yet. Add it now or skip."
if confirm "Add the Gemini API key now?"; then
  open_url "https://aistudio.google.com/app/apikey"
  step "Click 'Create API key'. Copy the key. Do not paste it into this terminal."
  open_url "https://script.google.com/d/${SCRIPT_ID}/edit"
  step "In the script editor, click Project Settings (the gear icon)."
  step "Under Script Properties, click 'Add script property'."
  step "Property: GEMINI_API_KEY. Value: paste the key. Click 'Save script properties'."
  pause "Press Enter when the property is saved."
fi

stage "Build the Sheet and Drive tree, and run one certificate"
open_url "https://script.google.com/d/${SCRIPT_ID}/edit"
step "Reload the script editor page now (F5). An editor opened before the push still holds the old code."
step "In the file list, open src/Code.gs."
step "In the function menu above the code, select setupDemo. Click Run."
step "Google asks for permission the first time. Pick your account. Click Allow."
step "Read the Execution log. The last line must say: Seeded Maple Court Residences. CERT-001 is in_review."
note "In Drive, the folder 'COI Compliance (Sample data)' now holds the data Sheet, _config, _inbox and Projects."
confirm "Did the log show CERT-001 is in_review?" || { warn "Copy the error from the log and give it to Claude."; exit 1; }
step "Select installUploadTrigger in the function menu. Click Run. The log must say: Installed the one-minute upload timer."
pause "Press Enter when the timer is installed."
step "Select installDailyTrigger in the function menu. Click Run. Google asks for the Calendar permission. Pick your account. Click Allow. The log must say: Installed the daily timer for 6 AM."
pause "Press Enter when the daily timer is installed."

stage "Deploy the internal app"
open_url "https://script.google.com/d/${SCRIPT_ID}/edit"
step "Click Deploy, then New deployment. Click the gear next to 'Select type'. Pick Web app."
step "Description: internal app."
step "Execute as: Me."
step "Who has access: 'Anyone with Google account' (docs/decisions.md). Never 'Anyone': the internal app needs a sign-in."
step "Click Deploy. Copy the Web app URL."
note "The upload page (ticket 04) is a different deployment with a different URL. Write 'internal' beside this one."
note "Before you test an upload link, open Deploy, Manage deployments, click the deployment described 'upload page' and copy its URL."
ask INTERNAL_APP_URL "Internal app URL:"
write_env INTERNAL_APP_URL "$INTERNAL_APP_URL"
say "Which 'Who has access' option did you pick?"
say "  1) Only myself   2) Anyone within your domain   3) Anyone with Google account   4) Anyone"
ask ACCESS_CHOICE "Type 1, 2, 3 or 4:"
case "$ACCESS_CHOICE" in
  1) INTERNAL_APP_ACCESS="only_myself" ;;
  2) INTERNAL_APP_ACCESS="domain" ;;
  3) INTERNAL_APP_ACCESS="anyone_with_google_account" ;;
  4) INTERNAL_APP_ACCESS="anyone_no_sign_in"
     warn "'Anyone' needs no sign-in. Edit the deployment and pick 'Anyone with Google account'." ;;
  *) warn "Not 1 to 4. Run the wizard again to record the access setting."; INTERNAL_APP_ACCESS="unknown" ;;
esac
write_env INTERNAL_APP_ACCESS "$INTERNAL_APP_ACCESS"
open_url "$INTERNAL_APP_URL"
step "The page must show one row: Ridgeline Roofing LLC, In review, None on file and a last action."
confirm "Does the page show that row?" || warn "Tell Claude what the page shows instead."

stage "Check: two deployments with different access"
say "The upload page (ticket 04) needs a second deployment that is open to anyone, with no sign-in."
say "This stage checks that one script project can hold both access settings at the same time."
open_url "https://script.google.com/d/${SCRIPT_ID}/edit"
step "Click Deploy, then New deployment. Pick Web app."
step "Description: access check. Execute as: Me. Who has access: Anyone. Click Deploy."
step "Copy the second Web app URL."
ask ACCESS_CHECK_URL "Second deployment URL:"
write_env ACCESS_CHECK_URL "$ACCESS_CHECK_URL"
step "Open a private (incognito) browser window."
step "In the private window, open the second URL. It must show the worklist with no sign-in."
step "In the private window, open the internal app URL. It must ask you to sign in."
step "In the editor, click Deploy, then Manage deployments. Check that each deployment still shows its own access."
if confirm "Did the second URL open with no sign-in while the internal app asked for one?"; then
  write_env TWO_DEPLOYMENTS_DIFFERENT_ACCESS "yes"
else
  write_env TWO_DEPLOYMENTS_DIFFERENT_ACCESS "no"
  warn "Then the upload page needs its own small script project (see the spec, Access)."
fi
step "Archive the access-check deployment now: Manage deployments, select it, click Archive."
note "It shows sample data only, but nothing should stay open to anyone without a reason."
pause "Press Enter when it is archived."

stage "Upload page address (Script Properties)"
say "Resend emails (ticket 05) carry a link to the public upload page. The app reads its address from a Script Property."
open_url "https://script.google.com/d/${SCRIPT_ID}/edit"
step "Click Deploy, then Manage deployments. Click the deployment described 'upload page'. It must say 'Who has access: Anyone'."
step "Copy that deployment's Web app URL. It is not the internal app URL."
ask UPLOAD_APP_URL "Upload page URL:"
write_env UPLOAD_APP_URL "$UPLOAD_APP_URL"
if [ "$UPLOAD_APP_URL" = "${INTERNAL_APP_URL:-}" ]; then
  warn "That is the internal app URL. Copy the URL of the deployment described 'upload page' instead."
fi
step "In the script editor, click Project Settings (the gear icon)."
step "Under Script Properties, click 'Add script property'."
step "Property: UPLOAD_BASE_URL. Value: the upload page URL. Click 'Save script properties'."
pause "Press Enter when the property is saved."

stage "Internal app address (Script Properties)"
say "The deficiency email (ticket 06) links the project manager to the record. The app reads its own address from a Script Property."
open_url "https://script.google.com/d/${SCRIPT_ID}/edit"
step "Click Deploy, then Manage deployments. Click the deployment described 'internal app'. It must say 'Who has access: Anyone with Google account'."
step "Copy that deployment's Web app URL. It is not the upload page URL."
ask INTERNAL_BASE_URL_VALUE "Internal app URL:"
if [ "$INTERNAL_BASE_URL_VALUE" = "${UPLOAD_APP_URL:-}" ]; then
  warn "That is the upload page URL. Copy the URL of the deployment described 'internal app' instead."
fi
step "In the script editor, click Project Settings (the gear icon)."
step "Under Script Properties, click 'Add script property'."
step "Property: INTERNAL_BASE_URL. Value: the internal app URL. Click 'Save script properties'."
pause "Press Enter when the property is saved."

finish
say "Give Claude these .env values to record in docs/decisions.md:"
say "WORKSPACE_EDITION, INTERNAL_APP_ACCESS, TWO_DEPLOYMENTS_DIFFERENT_ACCESS."
note "Do not share the URLs; they hold the domain."
